describe('Search Spelling Tolerance', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should return results when search query has minor spelling mistakes', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Perform search with a misspelled query
    cy.get('[data-testid="search-input"]').type('apple');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the API response
    cy.wait('@searchRequest');

    // Verify results are displayed
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify results contain the correct item despite misspelling
    cy.get('[data-testid="result-item"]').first().should('contain', 'Apple');
    cy.get('[data-testid="result-item"]').first().should('contain', 'fruit');
  });

  it('should handle multiple misspelled words and still return relevant results', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Perform search with multiple misspelled words
    cy.get('[data-testid="search-input"]').type('computrer');
    cy.get('[data-testid="search-input"]').type(' and');
    cy.get('[data-testid="search-input"]').type('programe');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the API response
    cy.wait('@searchRequest');

    // Verify results are displayed
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify results contain both corrected terms
    cy.get('[data-testid="result-item"]').first().should('contain', 'computer');
    cy.get('[data-testid="result-item"]').first().should('contain', 'program');
    cy.get('[data-testid="result-item"]').first().should('contain', 'software');
  });
});
